//! The libcpuid x86 CPU match tables, ported from fastfetch's
//! detection/cpu/cpu_x86.c (BSD-2-Clause, from
//! https://github.com/anrieff/libcpuid). Only the fields the matcher uses
//! are kept: family, model, stepping, ext_family, ext_model, the brand
//! pattern with its score, the codename and the process technology.

#[derive(Debug)]
pub struct MatchEntry {
    pub family: i32,
    pub model: i32,
    pub stepping: i32,
    pub ext_family: i32,
    pub ext_model: i32,
    pub pattern: &'static str,
    pub score: i32,
    pub name: &'static str,
    pub technology: &'static str,
}

